public class Button {
    private int size;
    private int width;
    private String color;

    public Button(int size, int width, String color) {
        this.size = size;
        this.width = width;
        this.color = color;
    }

    public int getSize() { return size; }
    public int getWidth() { return width; }
    public String getColor() { return color; }
}

tasks.solution:
public boolean isSameSize(Button other) {
    return this.size == other.size && this.width == other.width;
}

public boolean isSameColor(Button other) {
    return this.color.equals(other.color);
}

public static int countSame(Button[] arr, Button b) {
    int count = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i].isSameSize(b)) {
            count++;
        }
    }
    return count;
}

